scripts.script:
import java.nio.file.*


//File source = new File(project.basedir, "../../core/commons/src/main/java/org/cmdbuild/auth/role/RolePrivilege.java")
//File target = new File(project.build.sourceDirectory, "org/cmdbuild/auth/role/RolePrivilegeAuthority.java")

//def source = new File("${project.basedir}/../../core/commons/src/main/java/org/cmdbuild/auth/role/RolePrivilege.java")
//def target = new File("${project.build.sourceDirectory}/org/cmdbuild/auth/role/RolePrivilegeAuthority.java")

File source = new File(new File(project.basedir.toString()), "../../core/commons/src/main/java/org/cmdbuild/auth/role/RolePrivilege.java")
File target = new File(new File(project.build.sourceDirectory), "org/cmdbuild/auth/role/RolePrivilegeAuthority.java")



// Ensure directories exist
target.parentFile.mkdirs()

StringWriter writer = new StringWriter()

// --- 2. If target already exists, preserve header up to BEGIN marker ---
if (target.exists()) {
    def lines = target.readLines().iterator()
    String line
    while (lines.hasNext() && !(line = lines.next()).matches('\\s*/[*]\\s*BEGIN.*')) {
        writer.append(line + '\n')
    }
    // Keep the BEGIN line
    if (line != null) writer.append(line + '\n')
} else {
    // New file: create BEGIN marker
    writer.append("/* BEGIN RolePrivilegeAuthority */\n")
}

// --- 3. Inject constants based on RolePrivilege.java ---
source.eachLine { String l ->
    if (l.matches('\\s*RP_[A-Z_]+,?\\s*')) {
        writer.append(l.replaceFirst(/\s*RP_([A-Z_]+),?\s*/,
        'public static final String $1_AUTHORITY = "$1";\n'))
    }

}

// --- 4. Close with END marker, preserve footer if file existed ---
if (target.exists()) {
    def lines = target.readLines().iterator()
    String line
    // Skip until END
    while (lines.hasNext() && !(line = lines.next()).matches('\\s*/[*]\\s*END.*')) { }
    if (line != null) writer.append(line + '\n')

    // Copy remainder after END
    while (lines.hasNext()) {
        writer.append(lines.next() + '\n')
    }
} else {
    writer.append("/* END RolePrivilegeAuthority */\n")
}

// --- 5. Write new content ---
target.text = writer.toString()
println "[INFO] Generated: " + target
